import { useEffect, useState } from 'react';
import './StudentDashboard.css';
import api from '../../api';

export default function StudentDashboard({ currentUser, onLogout }) {
  const [activeTab, setActiveTab] = useState('assignments');
  const [assignments, setAssignments] = useState([]);
  const [leaderboard, setLeaderboard] = useState([]);
  const [loadError, setLoadError] = useState('');

  // Editor Modal State
  const [selectedAssignment, setSelectedAssignment] = useState(null);
  const [studentCode, setStudentCode] = useState('');
  const [output, setOutput] = useState('');
  const [submitting, setSubmitting] = useState(false);

  const loadAssignments = () => {
    api
      .listAssignments()
      .then(setAssignments)
      .catch((err) => setLoadError(err.message || 'Failed to load assignments'));
  };

  const loadLeaderboard = () => {
    api
      .getLeaderboard()
      .then((data) => setLeaderboard(data.entries || []))
      .catch(() => {});
  };

  useEffect(() => {
    loadAssignments();
    loadLeaderboard();
  }, []);

  const openCodeModal = (assignment) => {
    setSelectedAssignment(assignment);
    setStudentCode(
      assignment.submitted_code ||
        `// Write your ${assignment.language} solution here\n\nfunction solution() {\n  return true;\n}`
    );
    setOutput('');
  };

  const closeCodeModal = () => {
    setSelectedAssignment(null);
    setStudentCode('');
    setOutput('');
  };

  const handleRunCode = async () => {
    setOutput('▶ Compiling & Executing...');
    try {
      const result = await api.runCode(studentCode, selectedAssignment?.language || '');
      setOutput(result.output);
    } catch (err) {
      setOutput(`Error: ${err.message || 'Could not run code'}`);
    }
  };

  const handleSubmitAssignment = async () => {
    if (!selectedAssignment) return;

    setSubmitting(true);
    try {
      await api.submitAssignment(selectedAssignment.id, studentCode);
      alert(`Assignment "${selectedAssignment.title}" submitted successfully!`);
      closeCodeModal();
      loadAssignments();
      loadLeaderboard();
    } catch (err) {
      alert(err.message || 'Failed to submit assignment');
    } finally {
      setSubmitting(false);
    }
  };

  const completedCount = assignments.filter((a) => a.status === 'Submitted').length;
  const totalCount = assignments.length;
  const progressPercentage = totalCount > 0 ? Math.round((completedCount / totalCount) * 100) : 0;
  const pendingCount = assignments.filter((a) => a.status === 'Pending').length;

  return (
    <div className="student-container">
      {/* Header */}
      <header className="student-header" style={{ display: 'flex', justifyContent: 'space-between', alignItems: 'center' }}>
        <div>
          <h1 className="student-title">🎓 Student Portal</h1>
          <p className="student-subtitle">
            Welcome back, {currentUser?.full_name || 'Student'}! Track assignments, submit solutions, and monitor progress.
          </p>
        </div>
        {onLogout && (
          <button className="btn-secondary" onClick={onLogout} style={{ whiteSpace: 'nowrap', padding: '0.6rem 1.2rem' }}>
            🚪 Log Out
          </button>
        )}
      </header>

      {/* Navigation */}
      <nav className="student-nav" aria-label="Student Navigation">
        <button
          className={`student-nav-btn ${activeTab === 'assignments' ? 'active' : ''}`}
          onClick={() => setActiveTab('assignments')}
        >
          📚 Assignments {pendingCount > 0 && `(${pendingCount} Due)`}
        </button>

        <button
          className={`student-nav-btn ${activeTab === 'progress' ? 'active' : ''}`}
          onClick={() => setActiveTab('progress')}
        >
          📊 My Progress
        </button>

        <button
          className={`student-nav-btn ${activeTab === 'leaderboard' ? 'active' : ''}`}
          onClick={() => setActiveTab('leaderboard')}
        >
          🏆 Leaderboard
        </button>
      </nav>

      {loadError && <div className="error-banner" style={{ margin: '1rem 0' }}>{loadError}</div>}

      {/* Tab 1: Assignments */}
      {activeTab === 'assignments' && (
        <section>
          <div className="assignment-grid">
            {assignments.map((assignment) => (
              <article key={assignment.id} className="assignment-card">
                <div>
                  <div className="card-top">
                    <span className="badge-lang">{assignment.language}</span>
                    <span
                      className={`badge-status ${
                        assignment.status === 'Submitted' ? 'submitted' : 'pending'
                      }`}
                    >
                      {assignment.status === 'Submitted' ? '✓ Submitted' : '⏳ Pending'}
                    </span>
                  </div>

                  <h3 className="assignment-card-title">{assignment.title}</h3>
                  <p className="assignment-card-desc">{assignment.description}</p>
                  <div className="deadline-text">📅 Deadline: {assignment.deadline}</div>

                  {assignment.rating !== null && assignment.rating !== undefined && (
                    <div className="rating-badge">
                      ★ Rated: {assignment.rating} / 5
                    </div>
                  )}
                </div>

                <button
                  className={`btn-submit-action ${
                    assignment.status === 'Submitted' ? 'submitted-btn' : 'pending-btn'
                  }`}
                  onClick={() => openCodeModal(assignment)}
                >
                  {assignment.status === 'Submitted' ? 'View / Re-submit Solution' : 'Solve & Submit →'}
                </button>
              </article>
            ))}
          </div>
        </section>
      )}

      {/* Tab 2: My Progress */}
      {activeTab === 'progress' && (
        <section>
          <div className="progress-card">
            <h2 className="assignment-card-title" style={{ fontSize: '1.3rem' }}>Overall Course Completion</h2>
            <div className="progress-header">
              <span style={{ fontSize: '0.9rem', color: 'var(--text-secondary)' }}>
                {completedCount} of {totalCount} assignments completed
              </span>
              <strong style={{ fontSize: '1.1rem', color: 'var(--primary)' }}>{progressPercentage}%</strong>
            </div>

            <div className="progress-track" role="progressbar" aria-valuenow={progressPercentage} aria-valuemin="0" aria-valuemax="100">
              <div className="progress-bar-fill" style={{ width: `${progressPercentage}%` }} />
            </div>

            <p style={{ fontSize: '0.875rem', color: 'var(--text-muted)', margin: 0 }}>
              Keep submitting coursework before deadlines to maintain your progress and leaderboard rank.
            </p>
          </div>
        </section>
      )}

      {/* Tab 3: Leaderboard */}
      {activeTab === 'leaderboard' && (
        <section>
          <div className="leaderboard-container">
            <table className="leaderboard-table">
              <thead>
                <tr>
                  <th>Rank</th>
                  <th>Student Name</th>
                  <th>Submissions Completed</th>
                </tr>
              </thead>
              <tbody>
                {leaderboard.length === 0 && (
                  <tr className="leaderboard-row">
                    <td colSpan={3}>No submissions yet.</td>
                  </tr>
                )}
                {leaderboard.map((entry) => (
                  <tr
                    key={entry.student_id}
                    className={`leaderboard-row ${entry.student_name === currentUser?.full_name ? 'highlight-row' : ''}`}
                  >
                    <td>
                      {entry.rank === 1 ? '🥇' : entry.rank === 2 ? '🥈' : entry.rank === 3 ? '🥉' : ''} {entry.rank}
                    </td>
                    <td>
                      {entry.student_name}
                      {entry.student_id === currentUser?.id ? ' (You)' : ''}
                    </td>
                    <td>{entry.submissions_completed} Submissions</td>
                  </tr>
                ))}
              </tbody>
            </table>
          </div>
        </section>
      )}

      {/* Code Editor Modal */}
      {selectedAssignment && (
        <div className="modal-overlay" role="dialog" aria-modal="true">
          <div className="editor-modal-container">
            <h3 className="assignment-card-title" style={{ fontSize: '1.35rem' }}>{selectedAssignment.title}</h3>
            <p className="assignment-card-desc">{selectedAssignment.description}</p>

            <div className="code-block-label" style={{ marginBottom: '8px' }}>
              Code Workspace ({selectedAssignment.language})
            </div>

            <textarea
              className="editor-textarea"
              value={studentCode}
              onChange={(e) => setStudentCode(e.target.value)}
              spellCheck="false"
            />

            <div style={{ display: 'flex', gap: '10px', justifyContent: 'flex-end', flexWrap: 'wrap' }}>
              <button className="btn-success" onClick={handleRunCode}>
                ▶ Run Code
              </button>
              <button className="btn-primary" onClick={handleSubmitAssignment} disabled={submitting}>
                {submitting ? 'Submitting…' : 'Submit Assignment'}
              </button>
              <button className="btn-secondary" onClick={closeCodeModal}>
                Cancel
              </button>
            </div>

            {output && (
              <pre className="console-output">
                <code>{output}</code>
              </pre>
            )}
          </div>
        </div>
      )}
    </div>
  );
}
